                writer.WriteString("municipalityCode", buyer.MunicipalityCode);

            if (buyer.ProvinceCodeOption.IsSet)
                writer.WriteString("provinceCode", buyer.ProvinceCode);

            if (buyer.DeliveryDateOption.IsSet)
                writer.WriteString("deliveryDate", buyer.DeliveryDateOption.Value!.Value.ToString(DeliveryDateFormat));

            if (buyer.DeliveryContactOption.IsSet)
                writer.WriteString("deliveryContact", buyer.DeliveryContact);

            if (buyer.DeliveryAddressOption.IsSet)
                writer.WriteString("deliveryAddress", buyer.DeliveryAddress);

            if (buyer.AdditionalPhoneOption.IsSet)
                writer.WriteString("additionalPhone", buyer.AdditionalPhone);

            if (buyer.PurchaseOrderDateOption.IsSet)
                writer.WriteString("purchaseOrderDate", buyer.PurchaseOrderDateOption.Value!.Value.ToString(PurchaseOrderDateFormat));

            if (buyer.PurchaseOrderNumberOption.IsSet)
                writer.WriteString("purchaseOrderNumber", buyer.PurchaseOrderNumber);

            if (buyer.InternalCodeOption.IsSet)
                writer.WriteString("internalCode", buyer.InternalCode);

            if (buyer.PaymentResponsibleOption.IsSet)
                writer.WriteString("paymentResponsible", buyer.PaymentResponsible);

            if (buyer.AdditionalInfoOption.IsSet)
                writer.WriteString("additionalInfo", buyer.AdditionalInfo);
        }
    }
}
